def traversal(policy):
    if policy not in ("stack", "queue"):
        raise ValueError("Use stack or queue.")
    frontier = deque(["S"])
    visited, order = set(), []
    while frontier:
        node = frontier.pop() if policy == "stack" else frontier.popleft()
