    queue = deque([start])
    parents = {start: None}
    expanded = []
    trace = []
    while queue:
        node = queue.popleft()
        expanded.append(node)
        if node != goal:
            for neighbor in graph.get(node, []):
                if neighbor not in parents:
                    parents[neighbor] = node
                    queue.append(neighbor)
        trace.append({
            "node": node, "frontier": list(queue),
            "visited": list(parents), "parents": dict(parents),
