        if node == goal:
            path = []
            cursor = goal
            while cursor is not None:
                path.append(cursor)
                cursor = parents[cursor]
            return {"path": path[::-1], "expanded": expanded, "trace": trace}
    return {"path": [], "expanded": expanded, "trace": trace}


def breadth_first_path(start, goal):
